CREATE TABLE "public"."us_geographies" (
  "id" serial,
  "state_name" varchar(50) NOT NULL DEFAULT '',
  "state_usps" varchar(10) NOT NULL DEFAULT '',
  "county_name" varchar(50) NOT NULL DEFAULT '',
  "city_name" varchar(50) NOT NULL DEFAULT '',
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "is_del" int2 NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
)
;

CREATE INDEX "idx_us_geographies_keyword" ON "public"."us_geographies" USING btree (
  "state_usps",
  "county_name",
  "city_name"
);

